#!/usr/bin/env node
// Copies the country-flag-icons 3x2 SVG set into public/flags so the nav menu
// can serve a flag for any country the CMS grows into, without a runtime API
// call and without committing ~270 vendored SVGs to the repo.
//
// public/flags is gitignored and regenerated by `pnpm dev` and `pnpm build`.

import { createRequire } from 'node:module'
import { copyFile, mkdir, readdir, rm } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const require = createRequire(import.meta.url)
const clientRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const destination = path.join(clientRoot, 'public', 'flags')

const packageRoot = path.dirname(require.resolve('country-flag-icons/package.json'))
const source = path.join(packageRoot, '3x2')

// The package ships flags.css and flags.zip alongside the SVGs; neither belongs
// in public/.
const sourceFiles = (await readdir(source)).filter((name) => name.endsWith('.svg'))
if (sourceFiles.length === 0) {
  throw new Error(`No flag SVGs found in ${source}`)
}

// Already in sync: a no-op keeps `pnpm dev` startup cheap.
const existing = await readdir(destination).catch(() => null)
if (existing && existing.length === sourceFiles.length) {
  process.exit(0)
}

await rm(destination, { recursive: true, force: true })
await mkdir(destination, { recursive: true })
await Promise.all(
  sourceFiles.map((name) => copyFile(path.join(source, name), path.join(destination, name))),
)

console.log(`[flags] synced ${sourceFiles.length} flags -> public/flags`)
